def restore_w5_form_purpose(relative_path, raw):
    """Accept only an exact current or parent whole file; reject every other input."""
    if relative_path not in SPEC or type(raw) is not bytes:
        raise ValueError("unknown proof source path/type")
    entry = SPEC[relative_path]
    digest = hashlib.sha256(raw).hexdigest()
    if digest == entry["parent_sha256"] and len(raw) == entry["parent_bytes"]:
        return raw
    if digest != entry["candidate_sha256"] or len(raw) != entry["candidate_bytes"]:
        raise ValueError("candidate whole-source pin differs: " + relative_path)
    restored = raw
    for after, before in entry["edits"]:
        if not after or restored.count(after) != 1:
            raise ValueError("unique exact inverse hunk missing: " + relative_path)
        restored = restored.replace(after, before, 1)
    if len(restored) != entry["parent_bytes"] or hashlib.sha256(restored).hexdigest() != entry["parent_sha256"]:
        raise ValueError("restored parent whole-source pin differs: " + relative_path)
    return restored
